const j = $input.first().json;
const act_id = j.act_id || j.meta_ad_account_id || '';
const date_preset = j.date_preset || 'last_7d';
if (!act_id || !act_id.startsWith('act_')) {
  return [{ json: { error: 'act_id requerido (ej. act_123)' } }];
}
return [{ json: { act_id, date_preset } }];

const prep = $('Preparar params').first().json;
const campaignsItems = $('GET campañas activas').all();
const insightsItems = $('GET insights cuenta').all();
let campaigns = [];
let insights = null;
try {
  const c0 = campaignsItems[0]?.json;
  campaigns = Array.isArray(c0?.data) ? c0.data : [];
  if (c0?.error) campaigns = [];
} catch (_) { campaigns = []; }
try {
  const i0 = insightsItems[0]?.json;
  if (i0?.error) insights = null;
  else insights = Array.isArray(i0?.data) ? i0.data[0] : i0;
} catch (_) { insights = null; }
const spend = insights?.spend || '0';
const impr = insights?.impressions || 0;
const clic = insights?.clicks || 0;
const cpc = insights?.cpc || 'N/A';
let actions = insights?.actions || [];
let leads = 0;
let purchases = 0;
for (const a of actions) {
  if (a.action_type === 'lead') leads = a.value;
  if (a.action_type === 'purchase') purchases = a.value;
}
const output = {
  summary: { spend, impressions: impr, clicks: clic, cpc, leads, purchases, active_campaigns: campaigns.length },
  campaigns: campaigns.map(c => ({ id: c.id, name: c.name, status: c.effective_status || c.status })),
  raw_insights: insights
};
return [{ json: { output: JSON.stringify(output, null, 2) } }];
